[6442] = { en = "Naga at the Zoram Strand", tier = 1,
  t = "Naga op de Zoram Strand",
  d = "Er loert hier kwaad langs de kust, $r.$B$BHet is de rustplaats van de gedoemde stad Zoram. Die is lang geleden verwoest en onder de zee gezonken. Verloren en bijna vergeten.$B$BNu zijn de naga terug, en we weten niet waarom. Maar de reden is niet belangrijk. We moeten het land verdedigen. We hebben zo hard gewerkt om het van ons te maken.$B$BKom terug met 20 van hun hoofden! Gooi de naga terug in de diepte!",
  o = "Breng 20 Wrathtail Heads naar Marukai langs de Zoram Strand.",
  p = "Er komen steeds meer naga, $n. Doe deze taak alsjeblieft voor me.",
  c = "We kunnen hier meer van jouw soort gebruiken, $N. Bedankt voor je hulp.",
  g = { {"loert", "lurks (loeren)"}, {"kust", "coast"}, {"rustplaats", "resting place"}, {"gedoemde", "doomed (gedoemd)"}, {"verwoest", "destroyed (verwoesten)"}, {"gezonken", "sunk (zinken)"}, {"verdedigen", "defend"}, {"diepte", "depths"}, {"soort", "kind"} },
},

[6545] = { en = "Warsong Runner Update", tier = 1,
  t = "Bericht van de Warsong Runner",
  p = "Dus jij bent hier met mijn bevelen? Het is altijd fijn om een nieuwe rekruut te zien met veel energie en een sterke wil.$B$BJe moet snel leren als je het hier wilt bijhouden. De dreiging van de naga wordt groter, $N. Sinds ik hier ben, heb ik verschillende aanvallen op deze post gezien en me ertegen verdedigd.$B$BMaar als je wilt helpen, praat dan met een van de anderen hier op de post.",
  c = "Nou, mijn bericht zal dit allemaal aan Kadrak uitleggen. Breng het zo snel mogelijk naar hem terug.",
  g = { {"bericht", "message, update"}, {"bevelen", "orders (bevel)"}, {"rekruut", "recruit"}, {"wil", "will"}, {"bijhouden", "keep up"}, {"dreiging", "threat"}, {"aanvallen", "attacks (aanval)"}, {"verdedigd", "defended (verdedigen)"}, {"post", "outpost"} },
},

[6383] = { en = "The Ashenvale Hunt", tier = 1,
  t = "De jacht van Ashenvale",
  c = "Er zijn drie legendarische wezens die samen de Ashenvale Hunt vormen. Je kunt ze zoeken en jezelf testen tegen hun sluwheid en kracht. Hopelijk leer je daarbij ook iets over jezelf. De wezens zijn: de beer Ursangous, de nachtsabelkat Shadumbra en de hippogrief Sharptalon.$B$BDe wezens van de Ashenvale Hunt zijn sterk. Misschien heb je hulp nodig om ze te verslaan. Als je ze verslaat, breng me dan bewijs van je daad.",
  g = { {"jacht", "hunt"}, {"legendarische", "legendary (legendarisch)"}, {"wezens", "creatures (wezen)"}, {"sluwheid", "cunning"}, {"hopelijk", "hopefully"}, {"nachtsabelkat", "nightsaber cat"}, {"hippogrief", "hippogryph"}, {"verslaan", "defeat, best"}, {"bewijs", "proof"}, {"daad", "deed"} },
},

[6547] = { en = "Warsong Scout Update", tier = 2,
  t = "Bericht van de Warsong Scout",
  p = "Hou je ogen open, $R. De elfen verstoppen zich vaak in de schaduwen...$B$BWe moeten altijd opletten. We hebben heel hard gewerkt om dit land te veroveren, en de elfen zoeken een kans om het van ons af te pakken.$B$BIk neem aan dat je mijn volgende bevelen van Kadrak hebt?",
  c = "Laat Kadrak weten hoe goed het ons hier lukt om de nachtelfen tegen te houden. Onze plannen gaan goed.",
  g = { {"hou je ogen open", "keep an eye out"}, {"verstoppen zich", "hide (zich verstoppen)"}, {"schaduwen", "shadows (schaduw)"}, {"opletten", "watch out, pay attention"}, {"veroveren", "conquer, claim"}, {"af te pakken", "to take away (afpakken)"}, {"neem aan", "assume (aannemen)"}, {"bevelen", "orders (bevel)"}, {"tegen te houden", "to hold off (tegenhouden)"} },
},

[6641] = { en = "Vorsha the Lasher", tier = 2,
  t = "Vorsha the Lasher",
  d = "Vorsha the Lasher... de duivelse hydra die over de zeeën zwerft...$B$BZe heeft onze post aangevallen, elke keer zonder reden, en ze vernietigt alles wat op haar pad komt.$B$BMaar ik ben er klaar voor, $N. Ik heb me voorbereid om de hydra te verslaan en een einde te maken aan deze aanvallen op Zoram'gar.$B$BDe naga eren het slechte karakter van dit beest met een vuurschaal die altijd brandt, op een eiland vlak voor de kust. Ik denk dat Vorsha woedend zal verschijnen als we het vuur doven.$B$BWe hebben hulp nodig, dus neem een paar sterke bondgenoten mee.",
  o = "Houd Muglash veilig terwijl hij naar de vuurschaal reist. Help hem om het vuur in de vuurschaal te doven en bescherm hem dan terwijl je tegen de naga vecht.$B$BAls het lukt, ga dan terug naar de Zoram'gar Outpost en vertel de Warsong Runner dat Vorsha the Lasher dood is.",
  c = "Ik heb veel aanvallen van de naga gezien sinds ik hier ben. Het geeft me rust dat Vorsha niet meer vrij rond zal zwerven.$B$BWe staan bij je in het krijt, $N.",
  e = "Versla Vorsha the Lasher",
  g = { {"duivelse", "fiendish (duivels)"}, {"hydra", "hydra"}, {"zwerft", "roams (zwerven)"}, {"zonder reden", "unprovoked, without reason"}, {"voorbereid", "prepared (voorbereiden)"}, {"eren", "honour"}, {"vuurschaal", "brazier"}, {"woedend", "furious, in anger"}, {"doven", "put out, extinguish"}, {"bondgenoten", "allies (bondgenoot)"}, {"rust", "peace, ease"}, {"in het krijt", "in debt (bij iemand in het krijt staan)"} },
},

[23] = { en = "Ursangous's Paw", tier = 2,
  t = "De poot van Ursangous",
  d = "De poot van de machtige beer Ursangous is jouw trofee voor dit deel van de Ashenvale Hunt. Op de poot staat een klein embleem in de vorm van een kwart maansikkel; niemand weet wat het embleem betekent.$B$BBreng de poot naar Senani Thunderheart in Splintertree Post. Zo bewijs je dat je het machtige wezen hebt verslagen en dit deel van de jacht hebt voltooid.",
  o = "Breng Ursangous's Paw naar Senani Thunderheart in Splintertree Post, Ashenvale.",
  p = "Ah - $N - ik dacht net aan je! Hoe gaat het jagen?",
  c = "Ah, de poot van Ursangous! Je bent erg bekwaam, $c; hij heeft heel wat slachtoffers gemaakt. De sikkel op zijn poot is vast een teken dat hij getraind is door de nachtelfen die door Ashenvale sluipen. Ursangous is... was een van de machtigste beren die je hier in de buurt kon vinden. Dat je zo'n wezen hebt verslagen, bewijst je wilskracht en vastberadenheid.$B$BJe voorouders zouden trots zijn!",
  g = { {"poot", "paw"}, {"trofee", "trophy"}, {"embleem", "emblem"}, {"maansikkel", "crescent moon"}, {"voltooid", "completed (voltooien)"}, {"bekwaam", "skilled"}, {"slachtoffers", "victims, kills (slachtoffer)"}, {"sikkel", "crescent"}, {"sluipen", "skulk, sneak"}, {"wilskracht", "willpower"}, {"vastberadenheid", "resolve, determination"}, {"voorouders", "ancestors (voorouder)"} },
},

[216] = { en = "Between a Rock and a Thistlefur", tier = 2,
  t = "Tussen een rots en een Thistlefur",
  d = "De Thistlefur-furbolgs bedreigen onze uitbreiding! Thistlefur Village, ten oosten van ons, blokkeert de weg tussen ons hier en de Splintertree Post. Via die weg kunnen we om het dorp Astranaar heen gaan. Zonder die weg geven we de Alliance een extra uitbreidingsroute.$B$B$N, we mogen geen... gat in onze uitbreidingsroutes toestaan!$B$BGa naar Thistlefur Village en dun de furbolgs uit. Je krijgt een vergoeding voor deze taak, maar wat nog belangrijker is: je doet je plicht voor de Horde!",
  o = "Versla 12 Thistlefur Avengers en 12 Thistlefur Shaman; de meeste zijn ten oosten van de Zoram Strand, in Thistlefur Village. Ga daarna terug naar Karang Amakkar in Zoram'gar Outpost, Ashenvale.",
  p = "Heb je de strijd naar de Thistlefur gebracht? Met een vrije weg tussen onze basissen wordt onze kans om heel Ashenvale te veroveren veel groter.",
  c = "Goed gedaan, $c, goed gedaan! Ik blijf troepen sturen om de furbolgs uit te dunnen, maar nu kan ik tenminste rekenen op een andere weg zonder last van de Alliance. De verovering van Ashenvale door de Horde is nu volop bezig!$B$BJe hebt vandaag je loon verdiend, held. Ik groet je!",
  g = { {"bedreigen", "threaten"}, {"uitbreiding", "expansion"}, {"blokkeert", "blocks (blokkeren)"}, {"uitbreidingsroute", "expansion path"}, {"toestaan", "allow"}, {"dun uit", "thin out (uitdunnen)"}, {"vergoeding", "compensation, pay"}, {"plicht", "duty"}, {"strijd", "fight, battle"}, {"veroveren", "conquer, claim"}, {"last", "trouble, nuisance"}, {"verovering", "conquest"}, {"volop", "in full swing, fully"}, {"loon", "pay, wages"} },
},

[6462] = { en = "Troll Charm", tier = 2,
  t = "Trollenamulet",
  d = "Mijn familie reisde hierheen met veel heilige trollenamuletten, maar de Thistlefur-furbolgs vielen hen aan en doodden hen voordat ze Zoram'gar bereikten! Die gemene furbolgs!$B$BIk mis mijn broers en zussen die gedood zijn, maar we zien elkaar weer in het hiernamaals. Maar hun trollenamuletten zijn in deze wereld veel waard. Het is een schande dat de furbolgs ze hebben!$B$B$N, je moet de amuletten terughalen! Ze liggen in kisten in Thistlefur Hold, een grot aan het einde van Thistlefur Village, ten noorden van Astranaar.",
  o = "Breng 8 Troll Charms naar Mitsuwa in de Zoram'gar Outpost.",
  p = "Heb je de amuletten gevonden, $N? Elk moment dat de furbolgs die heilige voorwerpen hebben, kookt mijn bloed van woede!",
  c = "Je hebt ze gevonden! Dank je! Dank je, $N! Je weet niet hoe groot het is wat je voor me hebt gedaan.$B$BEen trol zonder $gzijn:haar; amulet is als een ork zonder $gzijn:haar; oorlogslittekens...$B$BWaardeloos.",
  g = { {"trollenamuletten", "troll charms (trollenamulet)"}, {"heilige", "sacred (heilig)"}, {"bereikten", "reached (bereiken)"}, {"gemene", "vile (gemeen)"}, {"hiernamaals", "afterlife"}, {"schande", "outrage, disgrace"}, {"amuletten", "charms (amulet)"}, {"terughalen", "retrieve, get back"}, {"kisten", "chests (kist)"}, {"grot", "cave"}, {"kookt mijn bloed", "my blood boils (koken)"}, {"oorlogslittekens", "battle scars (oorlogslitteken)"}, {"waardeloos", "worthless"} },
},

[6482] = { en = "Freedom to Ruul", tier = 2,
  t = "Vrijheid voor Ruul",
  d = "Hè? Wie ben jij?$B$B$N? Je bent geen furbolg. Ze zijn vervloekt! Ze dachten dat ik een beer was en hebben me gevangengenomen, en nu laten ze me verhongeren! Mijn kracht raakt op...$B$BHelp me ontsnappen en praat daarna met mijn zus Yama in de Splintertree Post, in het oosten.$B$B$N! Ik moet ontsnappen!",
  o = "Begeleid Ruul en praat daarna met Yama Snowhoof in Splintertree Post.",
  p = "Heb je mijn broer Ruul gezien? Hij is dagen geleden het bos in gelopen en is niet teruggekomen...",
  c = "Je hebt mijn broer gevonden! Hij was gevangengenomen door de Thistlefurs? Dat is vreselijk nieuws. Want hoewel veel furbolgs edele wezens zijn, zijn de Thistlefurs verdorven.$B$BBedankt dat je mijn broer hebt gered, $N. Ik wil er niet aan denken hoe ze de arme Ruul hebben behandeld. Hij zal na deze beproeving waarschijnlijk lang slapen...",
  e = "Begeleid Ruul weg van de Thistlefurs.",
  g = { {"vrijheid", "freedom"}, {"vervloekt", "cursed"}, {"gevangengenomen", "captured (gevangennemen)"}, {"verhongeren", "starve"}, {"raakt op", "is running out, failing (opraken)"}, {"ontsnappen", "escape"}, {"begeleid", "escort (begeleiden)"}, {"edele", "noble (edel)"}, {"verdorven", "corrupt"}, {"gered", "rescued (redden)"}, {"behandeld", "treated (behandelen)"}, {"beproeving", "ordeal"} },
},

[6503] = { en = "Ashenvale Outrunners", tier = 2,
  t = "Verkenners in Ashenvale",
  d = "We hebben berichten gekregen dat Ashenvale-verkenners niet lang geleden uit Silverwing Outpost zijn vertrokken. Nu sluipen ze in het bos in de buurt van ons gebied. We willen niet dat ze informatie verzamelen over onze verdediging!$B$BSluip door de bossen ten zuiden van onze post hier en ten oosten van Silverwing, de post van de Alliance. Zoek de verkenners, dood ze en kom dan terug naar mij.",
  o = "Dood 9 Ashenvale Outrunners en ga dan terug naar Kuray'bin in Splintertree Outpost.",
  p = "Ik wacht op berichten over de verkenners die je hebt gedood, $N.",
  c = "Heel goed, $N. Je jachtkunsten zijn indrukwekkend...$B$BHet verlies van die verkenners maakt de Alliance blind. En als ze geen informatie hebben, beginnen ze minder snel aanvallen.",
  g = { {"verkenners", "scouts, outrunners (verkenner)"}, {"berichten", "reports (bericht)"}, {"vertrokken", "left (vertrekken)"}, {"sluipen", "sneak"}, {"gebied", "territory"}, {"verzamelen", "gather"}, {"verdediging", "defences"}, {"jachtkunsten", "hunting skills (jachtkunst)"}, {"indrukwekkend", "impressive"}, {"verlies", "loss"} },
},

[6544] = { en = "Torek's Assault", tier = 2,
  t = "De aanval van Torek",
  d = "Hé! $C! Kom hier!$B$BMijn plunderaars en ik gaan zo de Silverwing Outpost in het westen aanvallen. Ons doelwit is de leider ervan, Duriel Moonfire. Verkenners melden dat de post zwaar verdedigd wordt door schildwachten en krijgers. Het wordt een glorieuze strijd!$B$BWil je de glorie delen, $N, en ons helpen? Zo ja, dan kun je na afloop ons succes melden bij mijn meerdere, Ertog Ragetusk in Splintertree.$B$BWat zeg je ervan? Doe je mee?",
  o = "Begeleid Torek bij zijn aanval op Silverwing Outpost en Duriel Moonfire, en meld je daarna bij Ertog Ragetusk in Splintertree Post.",
  p = "Torek is op missie gestuurd tegen Silverwing Outpost. Was de aanval een succes?",
  c = "Dus de aanval van Torek was een succes! Goed gedaan, $N. Nachtelfen zijn behoorlijke vijanden. Een beetje mager, maar sterk en fel! Ik weet zeker dat de strijd mooi was om te zien...$B$BEn ik hoop dat je er een litteken of twee aan hebt overgehouden!",
  e = "Verover Silverwing Outpost.",
  g = { {"plunderaars", "raiders (plunderaar)"}, {"doelwit", "target"}, {"melden", "report"}, {"schildwachten", "sentinels (schildwacht)"}, {"glorieuze", "glorious (glorieus)"}, {"na afloop", "afterwards, when it's over"}, {"meerdere", "superior"}, {"behoorlijke", "decent (behoorlijk)"}, {"mager", "skinny"}, {"fel", "fierce"}, {"litteken", "scar"}, {"overgehouden", "ended up with (overhouden)"}, {"verover", "take, conquer (veroveren)"} },
},

[25] = { en = "Stonetalon Standstill", tier = 2,
  t = "Stilstand naar Stonetalon",
  d = "Als je nuttig wilt zijn, waarom doe je dan niet iets aan de situatie bij Talondeep Path?$B$BHet transport tussen Ashenvale en Stonetalon staat stil, omdat het meer tot leven is gekomen en alles aanvalt wat te dichtbij komt... dus iedereen op het pad. Nog nuttiger dan de waterelementen daar hard aanpakken, is iemand die het prieel op Mystral Lake verkent - het prieel met een goed uitzicht op de post van de Alliance daar.$B$BHeb je zin om nuttig te zijn?",
  o = "Versla 12 Befouled Water Elementals bij Mystral Lake, recht ten oosten van het Talondeep Path en ten zuidwesten van Splintertree Post.$B$BVerken het prieel op Mystral Lake dat uitkijkt over de nabije post van de Alliance.$B$BGa terug naar Mastok Wrilehiss in Splintertree Post, Ashenvale.",
  p = "Ben je al terug? Hoe is de situatie daar - is alles nu opgelost, dankzij jou?",
  c = "Ja, ik hoorde dat iemand dat meer daar heeft omgewoeld als een stofhoos door de Barrens. Zo te horen kunnen we daar misschien ook een uitkijkpost opzetten om onze vrienden van de Alliance in de gaten te houden. Nou ja, als we het tenminste stil kunnen houden...$B$BHet lijkt erop dat je toch behoorlijk nuttig bent geweest; het transport tussen hier en Stonetalon zou het nu makkelijker moeten hebben. Neem dit - je hebt het verdiend.",
  e = "Verken het prieel op Mystral Lake dat uitkijkt over de nabije post van de Alliance.",
  g = { {"stilstand", "standstill"}, {"nuttig", "useful"}, {"staat stil", "is at a standstill (stilstaan)"}, {"hard aanpakken", "put the hammer down on, deal with firmly"}, {"prieel", "gazebo"}, {"verkent", "scouts (verkennen)"}, {"uitzicht", "view"}, {"uitkijkt over", "overlooks (uitkijken over)"}, {"nabije", "nearby (nabij)"}, {"omgewoeld", "churned up, tore up (omwoelen)"}, {"stofhoos", "dust devil"}, {"uitkijkpost", "observation post"}, {"in de gaten te houden", "to keep an eye on (in de gaten houden)"}, {"stil kunnen houden", "keep on the down low, keep quiet"} },
},

[6381] = { en = "New Life", tier = 2,
  t = "Nieuw leven",
  d = "Je hebt het gezien, $c: het land heeft pijn, maar de kringloop van het leven is sterk. Nu moeten wij ons deel doen om het te helpen. Plant deze zaden in het midden van de verwoesting, in het westen, in de Charred Vale. Pas op, want harpijen en boze vuurelementen plagen het beschadigde land nog steeds.$B$B$N, neem deze betoverde Gaea-zaden en plant ze in vruchtbare hopen aarde. De kringloop van het leven moet doorgaan!",
  o = "Plant 10 Gaea Seeds in Gaea Dirt Mounds en breng daarna de overgebleven Enchanted Gaea Seeds terug naar Tammra in Sun Rock Retreat.",
  p = "De zaden die je plant zijn sterk. Ze verzetten zich tegen verderf en maken een plek waar ander leven kan beginnen. Ze zullen groeien en groeien. Eerst houden ze het verderf tegen en genezen ze het beschadigde land. En op een dag maken ze van Stonetalon weer een weelderig bos.$B$BHeb je alle Gaea-zaden geplant?",
  c = "Dit is een grote overwinning voor het land. Na verloop van tijd zullen er nog meer dingen gebeuren: de Venture Co. zal haar cirkelzagen en bijlen inpakken, de boze vuurgeesten zullen kalm worden en het land zal de harpijen verdrijven.$B$BPas dan, $N, zal Stonetalon echt in vrede zijn.$B$BJe hebt het goed gedaan, $c. Neem een van deze voorwerpen als dank voor het nieuwe leven dat je hier vandaag hebt gemaakt.",
  o1 = "Gaea-zaad geplant",
  g = { {"kringloop", "cycle"}, {"verwoesting", "destruction"}, {"plagen", "plague, torment"}, {"beschadigde", "damaged, scarred (beschadigd)"}, {"betoverde", "enchanted (betoveren)"}, {"vruchtbare", "fertile (vruchtbaar)"}, {"verzetten zich tegen", "resist (zich verzetten tegen)"}, {"verderf", "corruption, ruin"}, {"weelderig", "lush"}, {"na verloop van tijd", "in time, after a while"}, {"cirkelzagen", "buzz saws (cirkelzaag)"}, {"verdrijven", "drive out"} },
},

[6393] = { en = "Elemental War", tier = 2,
  t = "Elementenoorlog",
  d = "Het Tribunal of the Tides heeft mij gestuurd om hier in Stonetalon Mountain oorlog te voeren tegen de vuurelementen. Neptulon the Tidehunter, heer van alle waterelementen, wil zelf graag zien dat onze vurige neven gedoofd worden.$B$B$N, je kunt me helpen om de gunst van het Tribunal te winnen. Vernietig de vuurelementen in de Charred Vale. Als ze vernietigd zijn, laten de vuurelementen Incendrites achter. Breng die naar mij en je krijgt een beloning.",
  o = "Breng 10 Incendrites naar Tsunaman in Sun Rock Retreat.",
  p = "Het Tribunal of the Tides wordt ongeduldig. Ze willen een einde maken aan deze oorlog, die al eeuwenlang in alle dimensies woedt. Mijn broeders willen graag nieuws horen over de glorieuze overwinning op de gehate vuurelementen. Heb je de Incendrites die ik nodig heb?",
  c = "De watergeesten in mij borrelen van opwinding. $N, je hebt me een glorieuze overwinning gegeven om aan het Tribunal of the Tides te melden.",
  g = { {"oorlog te voeren", "to wage war (oorlog voeren)"}, {"vurige", "fiery (vurig)"}, {"neven", "cousins (neef)"}, {"gedoofd", "extinguished (doven)"}, {"gunst", "favour"}, {"ongeduldig", "impatient"}, {"eeuwenlang", "for ages, for eons"}, {"woedt", "rages (woeden)"}, {"broeders", "brethren (broeder)"}, {"gehate", "hated (haten)"}, {"borrelen", "bubble"}, {"opwinding", "excitement"} },
},

[6546] = { en = "Warsong Outrider Update", tier = 2,
  t = "Bericht van de Warsong Outrider",
  p = "Er is veel gevaar langs dit pad, $N. Onthoud dat goed als je door deze landen reist. De dreiging van de Alliance is heel dichtbij.$B$BWe hebben aan alle kanten vijanden. De saters zijn een sterke en veelvoorkomende macht in het oosten van Ashenvale. Ik heb ook ontdekt dat de naga een groot deel van het land van Azshara hebben overgenomen.$B$BHet is goed om te zien dat we nog steeds meer troepen krijgen -- wees klaar voor wat je te wachten staat, $N.",
  c = "Breng mijn bericht naar Kadrak. Snel, $N.",
  g = { {"gevaar", "danger"}, {"onthoud", "remember (onthouden)"}, {"dreiging", "threat"}, {"aan alle kanten", "on all fronts, on all sides"}, {"saters", "satyrs (sater)"}, {"veelvoorkomende", "prevalent, common (veelvoorkomend)"}, {"macht", "force, power"}, {"ontdekt", "discovered (ontdekken)"}, {"overgenomen", "taken over (overnemen)"}, {"troepen", "troops (troep)"}, {"wat je te wachten staat", "what lies ahead"} },
},

[1058] = { en = "Jin'Zil's Forest Magic", tier = 2,
  t = "De bosmagie van Jin'Zil",
  d = "Ik ben zo opgewonden!$b$bDrie kleine kooien voor drie kleine elfjes! Maar wat zullen we doen met onze lieve boomknuffelende vrienden? Nou, laten we ze een beetje... hoe noemen ze het ook alweer... bosmagie laten proeven!$b$bIk heb een flinke hoop Stonetalon-sap nodig. Breng me wat twilight-snorharen van die afschuwelijke katten. Hier zijn natuurlijk ook heel veel courser-ogen voor nodig -- je kunt nooit genoeg ogen hebben. O, en laten we het niet vergeten: een kostbare schub van een fey-draak.$b$bSchiet op naar Stonetalon Peak, $n, zodat ik wat bosmagie kan brouwen!",
  o = "Witch Doctor Jin'Zil in Malaka'jin wil 5 porties Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes en een Fey Dragon Scale.",
  p = "Kijk naar onze arme kleine elfenvriendjes. Allemaal opgesloten, zonder bos om in te dartelen!$b$bHeb je wat sap voor me kunnen vinden? En de snorharen van de twilight runners? Je hebt die fey-drakenschub zeker niet bij je?$b$bEn ogen! Ik heb zoveel ogen nodig! Je kunt gewoon geen krachtig brouwsel met bosmagie maken zonder een flinke portie ogen!",
  c = "O, wat zullen deze kleine bosnimfen blij zijn! Met dit speciale brouwsel zullen ze zich helemaal thuis voelen!",
  g = { {"opgewonden", "excited"}, {"kooien", "cages (kooi)"}, {"boomknuffelende", "tree-hugging"}, {"proeven", "taste"}, {"flinke", "good, hefty (flink)"}, {"snorharen", "whiskers (snorhaar)"}, {"afschuwelijke", "horrid (afschuwelijk)"}, {"kostbare", "precious (kostbaar)"}, {"schub", "scale (of a fish or dragon)"}, {"brouwen", "brew"}, {"opgesloten", "locked up (opsluiten)"}, {"dartelen", "frolic"}, {"brouwsel", "brew, concoction"}, {"bosnimfen", "woodland nymphs (bosnimf)"} },
},

[6282] = { en = "Harpies Threaten", tier = 2,
  t = "Dreiging van harpijen",
  d = "Tauren zijn er trots op dat ze deze landen beschermen. Je kunt vast wel raden waarom ik geschrokken ben van het aantal harpijen dat hier in Stonetalon woont.$B$BDe Bloodfuries zijn de oorzaak van het groeiende aantal harpijen in Kalimdor. Ze dringen binnen bij allerlei soorten leven en houden de onschuldigen tegen als die hun gebied willen verlaten.$B$BDun de harpijen uit, $N!",
  o = "Maggran Earthbinder in Sun Rock Retreat wil dat je 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers en 7 Bloodfury Roguefeathers doodt.",
  p = "Wees voorzichtig in de Charred Vale; in die heuvels wonen veel slechte wezens. Blijf sterk, $N, dan zul je deze dreiging voor ons volk overwinnen. Ga nu en sla hard toe - onze kinderen zullen nooit iets weten van het kwaad dat er was.",
  c = "Dit is uitstekend nieuws! Vertel me nog eens hoe je angst hebt gezaaid in de koude harten van die gemene harpijen. De Bloodfuries hebben een zware klap gekregen!",
  g = { {"dreiging", "threat"}, {"geschrokken", "alarmed, shocked (schrikken)"}, {"oorzaak", "cause, source"}, {"dringen binnen", "encroach, intrude (binnendringen)"}, {"onschuldigen", "the innocent (onschuldige)"}, {"gebied", "area, territory"}, {"dun uit", "thin out, cull (uitdunnen)"}, {"overwinnen", "overcome, prevail"}, {"sla hard toe", "strike hard (toeslaan)"}, {"kwaad", "evil"}, {"angst hebt gezaaid", "cast fear, spread fear (angst zaaien)"}, {"gemene", "vile, nasty (gemeen)"}, {"klap", "blow"} },
},

[6283] = { en = "Bloodfury Bloodline", tier = 2,
  t = "De Bloodfury-bloedlijn",
  d = "Het is niet genoeg om het aantal Bloodfury Harpies kleiner te maken. De enige echte genezing voor hun ziekte is hun leider doden: Bloodfury Ripper!$B$BZe is bijna een koningin voor die smerige wezens. Dood haar, dan zal hun aantal zeker afnemen.$B$BGa terug naar de Charred Vale. Je vindt haar langs de westelijke heuvels. Ze zal niet makkelijk te verslaan zijn, maar de beloning zal groot zijn.",
  o = "Maggran in Sun Rock Retreat wil dat je Bloodfury Ripper doodt en haar overblijfselen meebrengt als bewijs van je daad.",
  p = "Bloodfury Ripper is een gemeen wezen! Je zult haar vinden langs de rij heuvels in het westen van de Charred Vale.$B$BDe Bloodfuries zullen hulpeloos zijn zonder... we kunnen ze zeker voor altijd verslaan!",
  c = "Ik voel de woede al uit me wegtrekken. Wat moet ik nu met mijn tijd doen? Omdat ik wist dat het kwaad vlak bij mijn land was, bleven mijn gedachten bezig. Maar nu zijn ze stil. Misschien is dit iets goeds... misschien kan ik me nu op het goede richten, zoals alle tauren zouden moeten doen.$B$BNeem dit alsjeblieft aan als beloning voor je moeite.",
  g = { {"bloedlijn", "bloodline"}, {"genezing", "cure, healing"}, {"smerige", "filthy (smerig)"}, {"afnemen", "diminish, decrease"}, {"verslaan", "defeat, vanquish"}, {"overblijfselen", "remains (overblijfsel)"}, {"bewijs", "proof"}, {"daad", "deed"}, {"hulpeloos", "helpless"}, {"woede", "anger, rage"}, {"wegtrekken", "drain away, leave"}, {"richten", "focus (zich richten op)"}, {"moeite", "trouble, effort"} },
},

[6441] = { en = "Satyr Horns", tier = 2,
  t = "Saterhoorns",
  d = "Hoi! Ik reis door Ashenvale op weg naar Ratchet en ik heb besloten om hier in Splintertree even te stoppen. Ik zoek altijd naar een kans, en het lijkt erop dat saterhoorns tegenwoordig erg gewild zijn in Ratchet.$B$BIk heb hier wat rondgevraagd, en het lijkt erop dat de saters in Night Run, Satyrnaar en Xavian allemaal het soort hoorns hebben dat ik zoek. Ik kan niet op tegen die saters... maar jij ziet eruit alsof jij dat wel kunt!$B$BWeet je wat: verzamel jij de hoorns voor me, dan zorg ik dat het de moeite waard is.",
  o = "Verzamel 16 Satyr Horns voor Pixel in Splintertree Post.",
  p = "Ik hoop dat je snel kunt zijn met die hoorns, $N. Ik ga binnenkort terug naar Ratchet!",
  c = "Deze zijn perfect, $N! Bedankt voor je hulp!$B$BO, en dit is voor je tijd...",
  g = { {"saterhoorns", "satyr horns (saterhoorn)"}, {"besloten", "decided (besluiten)"}, {"kans", "opportunity"}, {"tegenwoordig", "these days"}, {"gewild", "in demand"}, {"rondgevraagd", "asked around (rondvragen)"}, {"saters", "satyrs (sater)"}, {"kan niet op tegen", "am no match for (opkunnen tegen)"}, {"verzamel", "collect (verzamelen)"}, {"de moeite waard", "worth it, worth your time"}, {"binnenkort", "soon"} },
},

[6621] = { en = "King of the Foulweald", tier = 2,
  t = "Koning van de Foulweald",
  d = "$N, een andere stam furbolgs, de Foulweald, woont ten zuidoosten van Astranaar. Ze zijn niet zo talrijk als de Thistlefur, maar door hun woestheid zijn ze in de toekomst een gevaar. Met een machtsvertoon kunnen we dat gevaar wegnemen.$B$BNeem deze banier, ga naar het dorp van de Foulweald en zet hem op hun totemheuvel. Ze zullen proberen de banier te vernietigen, maar houd stand tot hun leider, Murgut, verschijnt om de eer van de stam te redden. Breng me de totem die hij draagt.$B$BVerzamel je bondgenoten, $N. Dit is geen taak voor één $c.",
  o = "Zet Karang's Banner op de Foulweald Totem Mound. Laat de furbolgs de banier niet vernietigen. Versla Chief Murgut en breng Murgut's Totem naar Karang Amakkar in Zoram'gar.",
  p = "Heb je Chief Murgut verslagen, $N? Heb je zijn Foulweald Totem meegebracht?",
  c = "Goed werk, $N. Door de Foulwealds uit te dagen en hun leider te verslaan, sturen we ze een duidelijke boodschap:$B$BMet de Horde valt niet te spotten.$B$BIk denk niet dat die stam ons voorlopig nog veel last zal geven.",
  g = { {"stam", "tribe"}, {"talrijk", "numerous"}, {"woestheid", "ferocity"}, {"machtsvertoon", "show of force"}, {"wegnemen", "remove"}, {"banier", "banner"}, {"totemheuvel", "totem mound"}, {"houd stand", "hold your ground (standhouden)"}, {"de eer van de stam te redden", "to save face for the tribe"}, {"bondgenoten", "allies (bondgenoot)"}, {"uit te dagen", "to challenge (uitdagen)"}, {"boodschap", "message"}, {"valt niet te spotten", "is not to be trifled with"}, {"voorlopig", "for the time being, for a long while"} },
},

[24] = { en = "Shadumbra's Head", tier = 2,
  t = "Het hoofd van Shadumbra",
  d = "De ooit zo snelle Shadumbra ligt nu stil terwijl je de overwinning opeist. Het hoofd van de verslagen nachtsabel is een passende trofee voor dit gevecht van de Ashenvale Hunt. Senani Thunderheart in Splintertree Post zal zo'n trofee willen zien om je dit deel van de Ashenvale Hunt toe te kennen.",
  o = "Breng Shadumbra's Head naar Senani Thunderheart in Splintertree Post, Ashenvale.",
  p = "Nogmaals gegroet, $N! Kom je me het bewijs van je jacht laten zien?",
  c = "Een overwinning voor $N in de Ashenvale Hunt! Goed gedaan - het hoofd van Shadumbra is zonder twijfel een passende trofee voor zo'n indrukwekkend gevecht.$B$BDe wreedheid van Shadumbra was overal op de post bekend. Elke tocht naar het westen, vooral te voet op weg naar de Zoram Strand, was vol gevaar door deze tijger. Dankzij jou is dat gevaar nu afgenomen.",
  g = { {"ooit", "once"}, {"opeist", "claim (opeisen)"}, {"verslagen", "slain, defeated (verslaan)"}, {"nachtsabel", "nightsaber"}, {"passende", "fitting (passend)"}, {"trofee", "trophy"}, {"toe te kennen", "to award (toekennen)"}, {"nogmaals gegroet", "greetings once again"}, {"zonder twijfel", "no doubt"}, {"wreedheid", "savagery, cruelty"}, {"te voet", "on foot"}, {"afgenomen", "abated, decreased (afnemen)"} },
},

[824] = { en = "Je'neu of the Earthen Ring", tier = 2,
  t = "Je'neu van de Earthen Ring",
  d = "De Earthen Ring is een groep sjamanen die de elementen bestudeert en beschermt. Ze zijn meer vergeten over gekke oude goden, oude legenden en overleveringen dan de meeste geleerden ooit zullen weten.$B$BJe hebt geluk, want ik ken iemand van de Earthen Ring hier in Ashenvale. Ga naar Zoram'gar Outpost aan de kust van de Zoram Strand en laat Je'neu Sancrea zien wat je gevonden hebt. Als iemand kan ontdekken wat die bol betekent, is hij het wel.",
  o = "Breng de Befouled Water Globe naar Je'neu Sancrea in Zoram'gar Outpost, Ashenvale.",
  p = "Ah, hallo. Ik besteed veel tijd aan het bestuderen van het water - eigenlijk van alle elementen - zoveel dat ik soms de mensen om me heen niet eens zie.$B$BKan ik je ergens mee helpen?",
  c = "Deze bol... hij is heel verontrustend. Veel van de sterkere elementen krijgen hun macht en energie via zulke voorwerpen. Er een te vinden die bijna heel is, is één ding - er een te vinden die zo bezoedeld is, is iets anders.$B$BIk zal ervoor zorgen dat de Earthen Ring deze bol goed bestudeert. Misschien kunnen we een einde maken aan dit bederf van de elementen. Neem dit alsjeblieft aan als eerlijke ruil, omdat je de Earthen Ring op deze bol hebt gewezen.",
  g = { {"sjamanen", "shamans (sjamaan)"}, {"bestudeert", "studies (bestuderen)"}, {"overleveringen", "lore, traditions (overlevering)"}, {"geleerden", "scholars (geleerde)"}, {"bol", "globe, sphere"}, {"besteed", "spend (besteden)"}, {"verontrustend", "disturbing"}, {"heel", "whole, intact"}, {"bezoedeld", "tainted, defiled (bezoedelen)"}, {"bederf", "corruption, decay"}, {"ruil", "exchange"}, {"gewezen", "pointed out, drawn attention to (wijzen op)"} },
},

[908] = { en = "Amongst the Ruins", tier = 2,
  t = "Tussen de ruïnes",
  d = "De Twilight's Hammer is de Moonshrine Ruins van Blackfathom Deeps binnengetrokken. Hun aanwezigheid kan er alleen voor zorgen dat de elementen gedwongen worden om tegen ons te werken. Als niemand ze tegenhoudt, wordt dit gebied voorgoed van hen.$B$B$N, ga Blackfathom in en zoek de fathom stone van de ruïnes; die zou ergens dichtbij in het water moeten liggen. Daarin zit een fathom core - een voorwerp dat, als je het goed leest, de geschiedenis van alle activiteit van de elementen vertelt. Als ik het heb, kunnen de Earthen Ring en ik misschien iets doen om ze te stoppen!",
  o = "Breng de Fathom Core naar Je'neu Sancrea in Zoram'gar Outpost, Ashenvale.",
  p = "Heb je de fathom core kunnen vinden? Zonder dat voorwerp hebben we geen idee wat de Twilight's Hammer daar beneden precies van plan is.",
  c = "Dit is precies wat ik nodig heb! Een fathom core is een ongelooflijke bron van informatie, waar we veel goeds uit kunnen halen. Wat de Twilight's Hammer daar ook van plan is - en geloof me, het is niets goeds - mijn kameraden en ik zullen het nu ontdekken.$b$bJe hebt het hier vandaag goed gedaan; de Earthen Ring kijkt met warmte naar je omdat je ons hebt geholpen. Je hebt ook de Horde als geheel geholpen, en daar mag je trots op zijn.",
  g = { {"ruïnes", "ruins (ruïne)"}, {"binnengetrokken", "moved into (binnentrekken)"}, {"aanwezigheid", "presence"}, {"gedwongen", "forced, coerced (dwingen)"}, {"tegenhoudt", "stops, checks (tegenhouden)"}, {"voorgoed", "for good"}, {"activiteit", "activity"}, {"van plan", "up to, planning"}, {"ongelooflijke", "incredible (ongelooflijk)"}, {"bron", "well, source"}, {"kameraden", "comrades (kameraad)"}, {"als geheel", "as a whole"} },
},

[5881] = { en = "Calling in the Reserves", tier = 2,
  t = "De reserves oproepen",
  d = "De Horde zorgt er goed voor dat onze troepen fris blijven... sinds de Grote Oorlog zijn we hier in Kalimdor welvarend geweest.$B$BIk wil dat je me een gunst bewijst. Ik heb een jongen die Grish Longrunner heet; hij beschermt de Great Lift in het zuiden van de Barrens. Geef hem deze brief. In de brief staat dat er een reservekrijger komt om hem af te lossen, zodat hij zijn familie kan bezoeken. Hij heeft hier een tijd geleden om gevraagd en hij zal blij zijn met het nieuws.",
  o = "Maggran wil dat je een brief bezorgt bij Grish Longrunner bij de Great Lift in de Barrens.",
  p = "Heb je nieuws van Maggran Earthbinder?",
  c = "Dit is geweldig nieuws; ik zit hier al veel te lang dit stuk hout te bewaken. Nu kan ik wat tijd met mijn familie doorbrengen... Joepie!",
  g = { {"oproepen", "call in, summon"}, {"troepen", "troops (troep)"}, {"welvarend", "prosperous"}, {"een gunst bewijst", "do a favour (een gunst bewijzen)"}, {"reservekrijger", "reserve warrior"}, {"af te lossen", "to relieve (of duty) (aflossen)"}, {"bezorgt", "deliver (bezorgen)"}, {"bewaken", "guard"}, {"doorbrengen", "spend (time)"}, {"Joepie", "Yippee"} },
},

[1088] = { en = "Ordanus", tier = 2,
  t = "Ordanus",
  d = "Ze dachten dat ze de stroom van magie konden stoppen. Ze vergisten zich. Ze dachten dat ze Ordanus konden verbergen, maar ik zal zijn hoofd krijgen!$b$bMagie geeft me echt zicht. Ja... daar is hij. Een kruispunt... Boven in een grote boom in Ashenvale Forest. Een naam... Raynewood. Een van de oudste zonen van de bosgod. Ze hebben hem stiekem van de top weggehaald voordat ik hem kon vinden, maar zijn tijd raakt op.$b$bBreng het naar mij en ik zal een machtig geschenk met je delen.",
  o = "Breng Ordanus' Head naar Braelyn Firehand bij Sun Rock Retreat.",
  p = "Toen mijn meester me naar de top van Stonetalon stuurde, dacht ik dat ik alleen de nachtelfen hoefde te vernietigen. Ze kropen rond in de heilige ruïnes van onze oude tempel van Azshara, en hun aanraking ontheiligde die heilige plek... maar Ordanus was me ontglipt.",
  c = "Ik kende Ordanus, lang geleden. Hij had de arrogantie van zijn soort en voelde zich zelfs beter dan de Highborne.$b$bZijn hoofd staat nu niet meer zo hoog, hè, $n?$b$bIk heb je een beloning beloofd en die zul je krijgen. Kom bij me.",
  g = { {"stroom", "flow, stream"}, {"vergisten zich", "were mistaken (zich vergissen)"}, {"zicht", "sight"}, {"kruispunt", "crossroads"}, {"stiekem", "secretly, on the sly"}, {"raakt op", "runs out (opraken)"}, {"geschenk", "gift"}, {"kropen rond", "crawled around (rondkruipen)"}, {"ruïnes", "ruins (ruïne)"}, {"aanraking", "touch"}, {"ontheiligde", "desecrated, despoiled (ontheiligen)"}, {"ontglipt", "slipped away from (ontglippen)"}, {"arrogantie", "arrogance"}, {"soort", "kind, species"} },
},

[1089] = { en = "The Den", tier = 2,
  t = "Het hol",
  d = "De druïden hebben de Talon Den op Stonetalon Peak gebouwd. Daar bewaren ze veel machtige voorwerpen.$b$bZe hebben een ingewikkeld plan bedacht, zodat die voorwerpen niet in verkeerde handen vallen.$b$bGelukkig heb ik... wat details uit een van hen weten te halen.$b$bVerborgen in een kleine lantaarn bij de ingang van de Den vind je de Gatekeeper's Key. Daarmee kun je bergplaatsen rond de Den openen. Met de voorwerpen uit die bergplaatsen kun je hun schat openen. Die ligt in een van de middelste ruimtes.",
  o = "Reis naar de Den op Stonetalon Peak. Gebruik de Gatekeeper's Key om de verborgen voorwerpen van de druïden te krijgen. Gebruik die voorwerpen om de Talon Den Hoard te openen.",
  p = "Er zijn drie sleutelgaten in de steen uitgehakt.",
  c = "Als de drie sleutels in de passende openingen schuiven, verschijnen er midden in het gloeiende licht een aantal voorwerpen.",
  g = { {"hol", "den, lair"}, {"druïden", "druids (druïde)"}, {"bewaren", "keep, store"}, {"ingewikkeld", "complex, complicated"}, {"bedacht", "devised (bedenken)"}, {"lantaarn", "lantern"}, {"ingang", "entrance"}, {"bergplaatsen", "caches, hiding places (bergplaats)"}, {"schat", "hoard, treasure"}, {"sleutelgaten", "keyholes (sleutelgat)"}, {"uitgehakt", "carved (uithakken)"}, {"passende", "matching (passend)"}, {"gloeiende", "glowing (gloeien)"} },
},

})

